-- ============================================================
-- SEED EXT 5: Módulo 15 — Gerund/Infinitive (ex 187-250)
-- Novos tópicos: gerunds/infinitives em TOEFL essays completos,
-- nominalizations avançadas, sequências complexas, academic style
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'gerund-infinitive';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo gerund-infinitive não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Gerunds como sujeito em frases acadêmicas
  (cid,51,187,'gap_fill','_____ (implement) evidence-based policy requires both rigorous research and the political capacity _____ (translate) findings into legislation.','Implementing / to translate',NULL,'Gerund as subject + infinitive after "capacity to."','easy'),
  (cid,51,188,'gap_fill','_____ (ignore) the distributional consequences of growth is not merely a moral failing; it risks _____ (undermine) the social cohesion that economic productivity requires.','Ignoring / undermining',NULL,'Gerund subject + gerund after "risk."','medium'),
  (cid,51,189,'gap_fill','_____ (achieve) sustainable development without _____ (address) inequality is increasingly regarded as impossible by development economists.','Achieving / addressing',NULL,'Gerund subject + gerund after "without" (preposition).','easy'),
  (cid,51,190,'multiple_choice','Which sentence uses the GERUND CORRECTLY as the subject of an academic claim?','Integrating environmental costs into price signals is widely recognized as a prerequisite for sustainable market outcomes.','["To integrating environmental costs is widely recognized.","Integrated environmental costs widely recognized as prerequisite.","Integrating environmental costs into price signals is widely recognized as a prerequisite for sustainable market outcomes.","Integrated environmental costs are a prerequisite."]','Gerund "integrating" as subject + "is recognized" (not "are").','medium'),
  (cid,51,191,'gap_fill','Consistently _____ (fail) _____ (address) structural drivers of poverty while _____ (focus) exclusively on symptomatic interventions is a pattern that development literature has documented repeatedly.','failing / to address / focusing',NULL,'Gerund phrase as subject: Failing + to address + focusing.','hard'),

  -- BLOCK 52: Infinitivos de propósito e resultado
  (cid,52,192,'gap_fill','The government has introduced a new regulatory framework _____ (ensure) that digital platforms _____ (cannot/evade) their obligations under data protection law.','to ensure / cannot evade',NULL,'Infinitive of purpose + result clause.','easy'),
  (cid,52,193,'gap_fill','Researchers designed the intervention _____ (maximize) behavioral engagement, _____ (allow) participants _____ (practice) the target skills in authentic contexts.','to maximize / allowing / to practice',NULL,'Infinitive of purpose + participial result + infinitive.','hard'),
  (cid,52,194,'gap_fill','The treaty was amended _____ (reflect) new scientific understanding, and signatories were required _____ (update) their national implementation plans within 18 months.','to reflect / to update',NULL,'Infinitive of purpose + required + infinitive.','easy'),
  (cid,52,195,'multiple_choice','Which sentence correctly uses an infinitive to express PURPOSE?','The committee established a working group to evaluate the feasibility of the proposed reforms.','["The committee established a working group for evaluate the feasibility.","The committee established a working group to evaluate the feasibility of the proposed reforms.","The committee established a working group for the evaluating of the feasibility.","The committee established a working group in order for evaluating the feasibility."]','"To + evaluate" = infinitive of purpose. "For + evaluating" would work with "for the purpose of."','easy'),
  (cid,52,196,'gap_fill','The research aims _____ (fill) a significant gap in the literature by _____ (provide) the first large-scale longitudinal evidence on X in _____ (develop) country contexts.','to fill / providing / developing',NULL,'"Aims to fill" + "by providing" + gerund adjective "developing."','hard'),

  -- BLOCK 53: Verbos de mudança de sentido avançados
  (cid,53,197,'gap_fill','After years of _____ (deny) the evidence, the company eventually _____ (stop) _____ (contest) the scientific consensus and _____ (begin) _____ (acknowledge) its products'' health impacts.','denying / stopped / contesting / began / to acknowledge',NULL,'"Stop + gerund" (ceased the action) + "begin + infinitive."','hard'),
  (cid,53,198,'gap_fill','The historian _____ (go on) _____ (describe) how the economic depression _____ (lead) to the collapse of democratic institutions in three countries; _____ (describe) this cascade of events _____ (take) nearly two chapters.','went on to describe / led / describing / took',NULL,'"Go on + to describe" (move to next topic) + gerund as new subject.','hard'),
  (cid,53,199,'multiple_choice','What is the DIFFERENCE in meaning between "The professor regretted telling the student" and "The professor regretted to tell the student"?','"Regretted telling" = felt sorry about having said it (past act). "Regretted to tell" = was sorry to inform (formal announcement).','["They are identical","''Regretted telling'' = past event already happened. ''Regretted to tell'' = formal, reluctant disclosure of information.","''Regretted telling'' = formal. ''Regretted to tell'' = informal.","Both mean the professor will say something regrettable."]','regret + gerund = past act one is sorry about. regret + to infinitive = formal/reluctant disclosure.','hard'),
  (cid,53,200,'gap_fill','The study _____ (try) _____ (address) a persistent gap in the literature; initial attempts _____ (try) _____ (use) smaller samples proved insufficient.','tries to address / trying to use / tried to use',NULL,'"Try + to infinitive" = attempt. "Try + gerund" = experiment with a method.','hard'),
  (cid,53,201,'gap_fill','Policymakers _____ (mean) _____ (introduce) the new regulations gradually, but the crisis _____ (mean) _____ (do) so would _____ (now/be) too late.','meant to introduce / meant that doing / would now be',NULL,'"Mean + to infinitive" = intend. "Mean + gerund" = involve/entail.','hard'),

  -- BLOCK 54: Gerunds após preposições em academic writing
  (cid,54,202,'gap_fill','The effectiveness of the intervention was contingent upon _____ (maintain) high fidelity to the protocol across all implementation sites.','maintaining',NULL,'"Contingent upon" + gerund.','easy'),
  (cid,54,203,'gap_fill','Rather than _____ (address) symptoms, effective policy should focus on _____ (identify) and _____ (remove) the structural barriers that perpetuate inequality.','addressing / identifying / removing',NULL,'"Rather than" + gerund + "focus on" + gerund.','easy'),
  (cid,54,204,'gap_fill','The success of collaborative governance models depends on _____ (build) mutual trust between stakeholders who may have competing interests, a process that _____ (resist) rapid _____ (scale).','building / resists / scaling',NULL,'"Depends on" + gerund + "resists" + gerund as object.','hard'),
  (cid,54,205,'multiple_choice','Which sentence correctly uses a GERUND after a preposition?','The committee is responsible for evaluating all submissions and for selecting the final recipient.','["The committee is responsible to evaluate all submissions and to select the final recipient.","The committee is responsible for evaluating all submissions and for selecting the final recipient.","The committee is responsible in evaluating and to select the final recipient.","The committee is responsible for to evaluate all submissions."]','"Responsible for" + gerund (preposition + gerund pattern).','easy'),
  (cid,54,206,'gap_fill','The organization is committed to _____ (promote) transparency and to _____ (ensure) that its decision-making processes _____ (subject/passive) to adequate external oversight.','promoting / ensuring / are subjected',NULL,'"Committed to" + gerund (NOT infinitive; "to" is a preposition here).','hard'),

  -- BLOCK 55: TOEFL Reading avançado
  (cid,55,207,'multiple_choice','[TOEFL Reading] "To achieve net zero emissions, economies will need to decarbonize their electricity systems while simultaneously electrifying transportation, heating, and industrial processes." The infinitive "to achieve" here functions as:','A purpose/goal clause setting up the conditions that follow.','["Part of a Type 2 conditional","A purpose/goal clause setting up the conditions that follow.","An infinitive after a main verb","A gerund functioning as subject"]','"To achieve..." = infinitive clause of purpose/condition framing the main argument.','medium'),
  (cid,55,208,'gap_fill','[TOEFL Reading] "_____ (find) sustainable solutions requires _____ (prioritize) systemic change over incremental adjustments." Best forms?','Finding / prioritizing',NULL,'Gerund as subject + gerund after "requires" as object.','easy'),
  (cid,55,209,'multiple_choice','[TOEFL Reading] "The study attempted to determine whether X causes Y." If rewritten to emphasize the attempt, the BEST nominalized version is:','The study''s attempt to determine whether X causes Y revealed methodological challenges.','["The study attempted determining whether X causes Y.","The study''s attempt to determine whether X causes Y revealed methodological challenges.","Attempting to determine whether X causes Y was what the study did.","The study''s attempting to determine whether X causes Y revealed challenges."]','Nominalization "attempt" + infinitive "to determine" = formal academic style.','hard'),

  -- BLOCK 56: TOEFL Speaking avançado
  (cid,56,210,'production','[TOEFL Speaking — 45s] A reading argues that reducing screen time improves children''s wellbeing. A lecture raises methodological concerns. Summarize using gerunds and infinitives.','',NULL,'The reading argues that limiting children''s screen time is essential for promoting healthy cognitive and social development. It claims that avoiding excessive exposure to digital media allows children to develop concentration skills, encourages face-to-face interaction, and helps prevent the anxiety and depression that have been associated with heavy social media use. However, the professor challenges several of the assumptions underlying this position. She begins by questioning the methodology of the studies the reading cites, noting that measuring the effects of screen time is complicated by the difficulty of distinguishing between passive consumption and active, educational use of digital tools. Furthermore, she argues that blaming screen time for concentrating on the specific types of content and platforms involved, since evidence suggests that the relationship between digital technology use and wellbeing varies substantially depending on what children are actually doing online. The professor concludes that rather than attempting to restrict screen time uniformly, a more effective approach would involve helping children develop the critical media literacy skills needed to use technology selectively and purposefully.','hard'),
  (cid,56,211,'production','[TOEFL Speaking — 45s] Discuss the advantages and disadvantages of outsourcing. Use gerunds and infinitives throughout.','',NULL,'Outsourcing — the practice of contracting specific business functions to external providers — has become a defining feature of the global economy, and evaluating its consequences requires examining both its economic efficiency and its social impacts. The primary advantage of outsourcing is reducing costs by accessing labor at lower wage rates, allowing companies to focus on their core competencies while delegating support functions to specialized providers. This can enable firms to scale operations rapidly without having to invest in building internal capacity. However, outsourcing also carries significant risks. Managing complex outsourcing relationships requires considerable coordination capability, and failing to maintain clear performance standards can result in quality deterioration that undermines the efficiency gains. From a social perspective, outsourcing often means eliminating stable domestic employment, and the workers displaced frequently find it difficult to transition to equivalent positions. Balancing efficiency considerations against employment and community impacts requires policymakers to make difficult choices about the degree to which market outcomes should be allowed to determine industrial structure.','hard'),

  -- BLOCK 57: TOEFL Writing avançado
  (cid,57,212,'production','[TOEFL Writing — 200 words] Write a paragraph on criminal justice reform using gerunds and infinitives throughout.','',NULL,'Reforming criminal justice systems requires simultaneously addressing the immediate costs of incarceration and the deeper social conditions that drive crime. Reducing reliance on incarceration as the primary response to criminal behavior is now supported by a substantial body of evidence showing that mass imprisonment does relatively little to deter crime while imposing enormous fiscal costs on public budgets and profound social costs on families and communities. Investing in early childhood education, mental health treatment, and substance abuse services has been shown in multiple jurisdictions to reduce crime rates more cost-effectively than building additional prison capacity. At the same time, enabling successful reintegration of people leaving prison requires addressing the barriers that make avoiding reoffending extremely difficult: lack of stable housing, difficulty obtaining employment with a criminal record, interrupted educational pathways, and severed family relationships. It would, however, be an oversimplification to argue that reforming criminal justice systems requires only scaling up social investment; the design of accountability mechanisms, the role of restorative justice practices, and the political economy of reform in communities that have been most affected by both crime and incarceration all deserve serious attention. Achieving genuinely equitable criminal justice is a long-term project that demands sustained political will.','hard'),
  (cid,57,213,'production','[TOEFL Writing — 200 words] Write a body paragraph on international migration using gerunds and infinitives to express complex ideas.','',NULL,'Managing international migration effectively requires governments to balance humanitarian obligations, economic interests, and political sustainability in ways that rarely align neatly with one another. Admitting asylum seekers and processing their claims fairly requires significant administrative capacity that many states have historically underinvested in, leading to backlogs that can keep asylum seekers waiting for years in conditions of uncertainty that inhibit integration and impose psychological costs. Restricting irregular migration is a stated priority of many governments, but reducing irregular entry without providing adequate legal pathways tends to push migration underground, making it more dangerous without reducing its volume. Integrating migrants successfully into receiving societies requires sustained investment in language training, credential recognition, and community support services; failing to provide these services tends to produce parallel social worlds that impede both migrants'' wellbeing and the development of mutual trust across communities. It is worth noting that developing cooperative agreements with sending and transit countries — to address the root causes of migration, to manage regular channels, and to facilitate return when appropriate — is considerably more effective than focusing exclusively on border enforcement. Understanding migration as a structural feature of an integrated global economy, rather than a crisis to be contained, is a necessary prerequisite for developing policy frameworks capable of governing it fairly and effectively.','hard'),

  -- BLOCK 58: Final
  (cid,58,214,'production','[TOEFL Writing — 200 words] Write a paragraph on environmental protection using gerunds and infinitives for nuanced academic style.','',NULL,'Protecting the natural environment requires resolving a fundamental tension between the economic logic of exploiting natural resources for immediate gain and the ecological logic of preserving ecosystem functions on which long-term human welfare depends. Pricing environmental externalities accurately — meaning treating the costs of pollution, resource depletion, and biodiversity loss as real costs rather than allowing them to be externalized onto society — is widely regarded as the most efficient mechanism for aligning market behavior with environmental sustainability. Implementing such pricing in practice requires overcoming powerful political opposition from industries whose profitability depends on the continued availability of unpriced environmental resources. Regulating specific harmful activities through command-and-control mechanisms remains important in areas where the damage from continued activity is too severe or irreversible to wait for price signals to shift behavior — particularly in protecting critical ecosystems and limiting the most toxic forms of pollution. Investing in environmental restoration — reforestation, wetland reconstruction, coral reef rehabilitation — is increasingly recognized not merely as a conservation measure but as an economic one: natural ecosystems provide services including carbon sequestration, water purification, flood mitigation, and biodiversity that sustaining agricultural productivity depends upon. Achieving environmental protection at the scale the evidence demands will require transforming it from a sectoral concern into a cross-cutting dimension of economic and social policy.','hard'),
  (cid,58,215,'production','[TOEFL Speaking — 60s] Discuss what developing countries can do to improve governance. Use gerunds and infinitives throughout.','',NULL,'Improving governance in developing countries is one of the most consequential and most contested challenges in international development, and identifying effective strategies requires moving beyond generic prescriptions to understand the specific constraints that different institutional contexts impose. Strengthening the capacity of public institutions to deliver services reliably requires sustained investment in human resources, salary structures adequate to attract and retain qualified personnel, and systems of accountability that make corruption costly rather than rewarding. Establishing effective mechanisms for holding leaders accountable to citizens — through credible elections, independent judiciaries, and free media — is widely regarded as the foundation of good governance, though building these institutions takes decades and cannot be achieved by importing institutional models without attending to the social and political conditions that make them work. Reducing the extractive use of state resources by elite groups requires political settlements that distribute the benefits of public power more broadly; achieving this is rarely possible through technical advice alone and depends on shifts in the balance of political power. International actors can support governance reform by financing public institutions, sharing knowledge, and conditioning aid on governance standards, but expecting external pressure to drive governance improvement against the preferences of domestic elites has a poor track record. Ultimately, governance reform is a political project that must be driven by domestic coalitions committed to building states that work for broad populations rather than narrow interests.','hard'),
  (cid,58,216,'production','[TOEFL Writing — Final 200 words] Write a paragraph on global trade governance using gerunds and infinitives with precision.','',NULL,'Governing international trade effectively requires reconciling the efficiency gains from openness with the legitimate needs of states to regulate in the public interest, and managing this tension has become increasingly difficult as trade agreements have expanded to cover domains — intellectual property, investment, and services — that overlap substantially with core domestic regulatory choices. Negotiating trade agreements that balance market access with policy space requires trading partners with different levels of development and different regulatory traditions to reach agreements that serve their respective interests, a process that is structurally biased toward the preferences of larger economies with greater negotiating leverage. Enforcing trade rules through the dispute settlement systems of the World Trade Organization has proved effective in constraining overt protectionism, but ensuring that the rules address new challenges — digital trade, state-owned enterprises, subsidies for strategic industries — has become increasingly difficult as political consensus among major trading nations has fragmented. Reviving multilateral trade cooperation requires rebuilding trust between major trading nations, including the United States and China, whose strategic competition has introduced geopolitical considerations into trade policy in ways that undermine the logic of comparative advantage. Sustaining an open trading system that is seen as fair and mutually beneficial, rather than as a mechanism for extracting advantages at others'' expense, is ultimately a political achievement that depends on leadership commitments that markets alone cannot generate.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
